create table if not exists inventory_ledger_transactions (id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,transaction_type text not null check(transaction_type in ('opening','purchase','consumption','waste','adjustment','transfer','receipt','reversal')),reference_type text,reference_id uuid,actor_user_id uuid references auth.users(id),idempotency_key text,created_at timestamptz not null default now(),unique(business_id,idempotency_key));
create table if not exists inventory_ledger_entries (id bigint generated always as identity primary key,transaction_id uuid not null references inventory_ledger_transactions(id) on delete restrict,business_id uuid not null references businesses(id) on delete cascade,ingredient_id uuid not null references ingredients(id) on delete restrict,location_id uuid references inventory_locations(id) on delete restrict,batch_id uuid references inventory_batches(id) on delete restrict,unit text not null,quantity numeric(24,8) not null check(quantity<>0),unit_cost_minor bigint not null default 0 check(unit_cost_minor>=0),entry_hash text,created_at timestamptz not null default now());
create index if not exists idx_v20_ledger_transaction on inventory_ledger_entries(transaction_id,id);
create index if not exists idx_v20_ledger_tenant_ingredient on inventory_ledger_entries(business_id,ingredient_id,created_at desc);
create unique index if not exists ux_v20_ledger_entry_hash on inventory_ledger_entries(entry_hash) where entry_hash is not null;
create or replace function public.v20_hash_inventory_entry(p_transaction_id uuid,p_business_id uuid,p_ingredient_id uuid,p_location_id uuid,p_batch_id uuid,p_unit text,p_quantity numeric,p_unit_cost_minor bigint,p_previous_hash text) returns text language sql immutable as $$ select encode(digest(concat_ws('|',coalesce(p_transaction_id::text,''),coalesce(p_business_id::text,''),coalesce(p_ingredient_id::text,''),coalesce(p_location_id::text,''),coalesce(p_batch_id::text,''),p_unit,p_quantity::text,p_unit_cost_minor::text,coalesce(p_previous_hash,'')),'sha256'),'hex') $$;
create or replace function public.v20_inventory_append_guard() returns trigger language plpgsql security definer set search_path=public as $$ declare prev text; begin perform pg_advisory_xact_lock(hashtextextended('NABUUMA|INVENTORY_LEDGER|V2.0',0)); select e.entry_hash into prev from inventory_ledger_entries e where e.business_id=new.business_id order by e.id desc limit 1; new.entry_hash:=v20_hash_inventory_entry(new.transaction_id,new.business_id,new.ingredient_id,new.location_id,new.batch_id,new.unit,new.quantity,new.unit_cost_minor,prev); return new; end; $$;
drop trigger if exists trg_v20_inventory_append on inventory_ledger_entries;
create trigger trg_v20_inventory_append before insert on inventory_ledger_entries for each row execute function v20_inventory_append_guard();
create or replace function public.v20_inventory_immutable_guard() returns trigger language plpgsql as $$ begin raise exception 'Inventory ledger entries are immutable'; end; $$;
drop trigger if exists trg_v20_inventory_immutable on inventory_ledger_entries;
create trigger trg_v20_inventory_immutable before update or delete on inventory_ledger_entries for each row execute function v20_inventory_immutable_guard();
create or replace function public.v20_assert_transaction_balanced(p_transaction_id uuid) returns void language plpgsql security definer set search_path=public as $$ declare n integer; tenant uuid; begin select count(*),min(business_id) into n,tenant from inventory_ledger_entries where transaction_id=p_transaction_id; if n=0 then raise exception 'Transaction has no inventory entries'; end if; if exists(select 1 from inventory_ledger_entries where transaction_id=p_transaction_id and business_id<>tenant) then raise exception 'Cross-tenant inventory transaction'; end if; end; $$;
create or replace function public.v20_append_inventory_transaction(p_business_id uuid,p_transaction_type text,p_reference_type text,p_reference_id uuid,p_idempotency_key text,p_entries jsonb) returns uuid language plpgsql security definer set search_path=public as $$ declare tx uuid; x jsonb; total integer:=0; q numeric(24,8); u text; begin if not has_role(p_business_id,ARRAY['owner','manager']::member_role[]) then raise exception 'Manager authorization required'; end if; if p_entries is null or jsonb_typeof(p_entries)<>'array' or jsonb_array_length(p_entries)=0 then raise exception 'Inventory transaction requires entries'; end if; perform pg_advisory_xact_lock(hashtextextended('NABUUMA|INVENTORY_LEDGER|V2.0',0)); select id into tx from inventory_ledger_transactions where business_id=p_business_id and idempotency_key=p_idempotency_key for update; if tx is not null then return tx; end if; tx:=gen_random_uuid(); insert into inventory_ledger_transactions(id,business_id,transaction_type,reference_type,reference_id,actor_user_id,idempotency_key) values(tx,p_business_id,p_transaction_type,p_reference_type,p_reference_id,auth.uid(),p_idempotency_key); for x in select * from jsonb_array_elements(p_entries) loop if coalesce(x->>'ingredient_id','')='' or coalesce(x->>'unit','')='' then raise exception 'Inventory entry requires ingredient_id and unit'; end if; q:=(x->>'quantity')::numeric; u:=x->>'unit'; if q=0 then raise exception 'Inventory quantity cannot be zero'; end if; if not exists(select 1 from ingredients where id=(x->>'ingredient_id')::uuid and business_id=p_business_id and base_unit=u) then raise exception 'Ingredient or exact unit mismatch'; end if; insert into inventory_ledger_entries(transaction_id,business_id,ingredient_id,location_id,batch_id,unit,quantity,unit_cost_minor) values(tx,p_business_id,(x->>'ingredient_id')::uuid,nullif(x->>'location_id','')::uuid,nullif(x->>'batch_id','')::uuid,u,q,coalesce((x->>'unit_cost_minor')::bigint,0)); total:=total+1; end loop; if total=0 then raise exception 'No inventory entries appended'; end if; perform v20_assert_transaction_balanced(tx); return tx; end; $$;
alter table inventory_ledger_transactions enable row level security;
alter table inventory_ledger_entries enable row level security;
create policy v20_inventory_tx_select on inventory_ledger_transactions for select using(is_member(business_id));
create policy v20_inventory_entries_select on inventory_ledger_entries for select using(is_member(business_id));
revoke all on function public.v20_append_inventory_transaction(uuid,text,text,uuid,text,jsonb) from public,anon,authenticated;
grant execute on function public.v20_append_inventory_transaction(uuid,text,text,uuid,text,jsonb) to authenticated;
revoke all on function public.v20_hash_inventory_entry(uuid,uuid,uuid,uuid,uuid,text,numeric,bigint,text) from public,anon,authenticated;
grant execute on function public.v20_hash_inventory_entry(uuid,uuid,uuid,uuid,uuid,text,numeric,bigint,text) to authenticated;